CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS monitored_databases (id SERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, host VARCHAR(255), port INTEGER DEFAULT 5432, db_name VARCHAR(255), db_type VARCHAR(50) DEFAULT 'PostgreSQL', status VARCHAR(50) DEFAULT 'healthy', size_mb NUMERIC DEFAULT 0, total_queries INTEGER DEFAULT 0, slow_queries INTEGER DEFAULT 0, uptime_hours NUMERIC DEFAULT 0, last_check TIMESTAMP, created_by INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS query_logs (id SERIAL PRIMARY KEY, database_id INTEGER REFERENCES monitored_databases(id) ON DELETE CASCADE, query_text TEXT, execution_time_ms INTEGER, status VARCHAR(50) DEFAULT 'completed', table_name VARCHAR(255), query_type VARCHAR(50), created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS suggested_indexes (id SERIAL PRIMARY KEY, database_id INTEGER REFERENCES monitored_databases(id) ON DELETE CASCADE, table_name VARCHAR(255), column_name VARCHAR(255), index_type VARCHAR(50) DEFAULT 'btree', impact_score NUMERIC DEFAULT 0, status VARCHAR(50) DEFAULT 'suggested', created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS backups (id SERIAL PRIMARY KEY, database_id INTEGER REFERENCES monitored_databases(id) ON DELETE CASCADE, backup_type VARCHAR(50) DEFAULT 'full', size_mb NUMERIC DEFAULT 0, status VARCHAR(50) DEFAULT 'completed', file_path TEXT, started_at TIMESTAMP DEFAULT NOW(), completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS db_logs (id SERIAL PRIMARY KEY, database_id INTEGER REFERENCES monitored_databases(id) ON DELETE CASCADE, agent VARCHAR(100), action VARCHAR(255), status VARCHAR(50) DEFAULT 'info', message TEXT, duration_ms INTEGER, created_at TIMESTAMP DEFAULT NOW());
